package servers_test

// L756H (THROWAWAY ab/l756h-diag-20261116, not for merge): the registry columns of the RULE 74 A/B with an A/A twin whose base is MAIN, of #756 step two without the loop reserve (celeris draft PR #1308: the WebSocket
// per-chunk allocation cut alone on main) (servers/l756h_arms.go, generated by l756h-gen.py). The expectations are stated here, not derived from the code under test; the three pins come from servers/celeris/go.mod (arms a, a2 and the
// control), servers/celeris_pr_c/go.mod (arms b, bg: the PR #1308 head) and servers/celeris_pr1307/go.mod (arm r: the PR #1307 head), and servers/celeris_pr_c and servers/celeris_pr1307 must be byte copies of the
// servers/celeris adapter sources (only the module path, the celeris pin and the go.sum differ: celeris is the ONLY thing that differs between the arms).

import (
	"bytes"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

// arm -> the exact column env (every column also carries the sampler).
var l756hWant = map[string]map[string]string{
	"a":   {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"a2":  {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"b":   {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"r":   {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"bg":  {"PROBATORIUM_SCHED_SAMPLE": "1", "GOGC": "400"},
	"ctl": {"PROBATORIUM_SCHED_SAMPLE": "1"},
}

var l756hName = regexp.MustCompile(`^l756h-([0-9]{3})-r([1-5])-(a|a2|b|r|bg|ctl)-(epoll-h1-sync|std-h1)$`)
var l756hPinRe = regexp.MustCompile(`(?m)^\s*github\.com/goceleris/celeris (v\S+)\s*$`)

func l756hPin(t *testing.T, dir string) string {
	t.Helper()
	mod, err := os.ReadFile(filepath.Join(dir, "go.mod"))
	if err != nil {
		t.Fatal(err)
	}
	m := l756hPinRe.FindSubmatch(mod)
	if m == nil {
		t.Fatalf("no celeris require in %s/go.mod", dir)
	}
	return string(m[1])
}

func l756hItoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b []byte
	for ; n > 0; n /= 10 {
		b = append([]byte{byte('0' + n%10)}, b...)
	}
	return string(b)
}

func TestL756HColumns(t *testing.T) {
	var cols []servers.Adapter
	for n, a := range servers.Registry {
		if strings.HasPrefix(n, "l756h-") {
			cols = append(cols, a)
		}
	}
	sort.Slice(cols, func(i, j int) bool { return cols[i].Name < cols[j].Name })
	if len(cols) != 30 {
		t.Fatalf("%d l756h columns, want 30 (5 reps x 6 arms)", len(cols))
	}
	mainPin, cPin, gPin := l756hPin(t, "celeris"), l756hPin(t, "celeris_pr_c"), l756hPin(t, "celeris_pr1307")
	if mainPin == cPin || cPin == gPin || mainPin == gPin {
		t.Fatalf("the three modules pin %s / %s / %s: there is no A/B", mainPin, cPin, gPin)
	}
	perRep := map[string]map[string]int{}
	baseLoop, baseCtl := servers.Registry["celeris-epoll-h1-sync"], servers.Registry["celeris-std-h1"]
	for i, a := range cols {
		mm := l756hName.FindStringSubmatch(a.Name)
		if mm == nil {
			t.Fatalf("column name %q", a.Name)
		}
		seq, rep, arm, eng := mm[1], mm[2], mm[3], mm[4]
		if want := i + 1; seq != strings.Repeat("0", 3-len(l756hItoa(want)))+l756hItoa(want) {
			t.Errorf("%s: seq %s is not the sorted position %d", a.Name, seq, want)
		}
		if perRep[rep] == nil {
			perRep[rep] = map[string]int{}
		}
		perRep[rep][arm]++
		base := baseLoop
		if arm == "ctl" {
			base = baseCtl
		}
		if (arm == "ctl") != (eng == "std-h1") || a.Engine != eng || a.Engine != base.Engine || a.Capabilities != base.Capabilities || a.Category != base.Category || a.Language != base.Language {
			t.Errorf("%s: engine / capabilities differ from its base column", a.Name)
		}
		wantMod, wantPin := "servers/celeris", mainPin
		switch arm {
		case "b", "bg":
			wantMod, wantPin = "servers/celeris_pr_c", cPin
		case "r":
			wantMod, wantPin = "servers/celeris_pr1307", gPin
		}
		if a.Framework != "celeris-l756h-"+arm || a.FrameworkVersion != wantPin {
			t.Errorf("%s: framework %s version %s, want celeris-l756h-%s / %s", a.Name, a.Framework, a.FrameworkVersion, arm, wantPin)
		}
		if gb, ok := a.Bin.(servers.GoBinary); !ok || gb.ModuleDir != wantMod {
			t.Errorf("%s: bin %#v, want module %s", a.Name, a.Bin, wantMod)
		}
		want := l756hWant[arm]
		if len(a.SUTEnv) != len(want) {
			t.Errorf("%s: SUTEnv %v, want %v", a.Name, a.SUTEnv, want)
		}
		for k, v := range want {
			if a.SUTEnv[k] != v {
				t.Errorf("%s: SUTEnv[%s] = %q, want %q", a.Name, k, a.SUTEnv[k], v)
			}
		}
		p, ok := a.RatedPlans["ws-large-echo"]
		if !ok || len(a.RatedPlans) != 1 || len(p.Fractions) != 0 || len(p.AbsoluteRPS) != 3 || p.AbsoluteRPS[0] != 8376 || p.AbsoluteRPS[1] != 16753 || p.AbsoluteRPS[2] != 25129 || p.Placeholder || p.SaturationOnly {
			t.Errorf("%s: rated plans %#v, want exactly ws-large-echo: no fractions, absolute 8376, 16753 and 25129", a.Name, a.RatedPlans)
		}
		if a.Baseline {
			t.Errorf("%s: Baseline is set", a.Name)
		}
	}
	for rep, arms := range perRep {
		if len(arms) != 6 {
			t.Errorf("rep %s has %d arms, want 6", rep, len(arms))
		}
		for arm, n := range arms {
			if n != 1 {
				t.Errorf("rep %s arm %s %d times", rep, arm, n)
			}
		}
	}
	if len(perRep) != 5 {
		t.Errorf("%d reps, want 5", len(perRep))
	}
}

// TestL756HModulesAreByteCopiesOfTheMainModule: every arm differs from main by the celeris pin ONLY (RULE 74: nothing else may move). Every file of servers/celeris is in servers/celeris_pr_c and servers/celeris_pr1307 with the
// same bytes, except go.mod / go.sum (the module path and the celeris pin / its sums); no extra file.
func TestL756HModulesAreByteCopiesOfTheMainModule(t *testing.T) {
	ents, err := os.ReadDir("celeris")
	if err != nil {
		t.Fatal(err)
	}
	for _, mod := range []string{"celeris_pr_c", "celeris_pr1307"} {
		seen := map[string]bool{}
		for _, e := range ents {
			if e.IsDir() {
				t.Errorf("servers/celeris has a directory %s: the byte-copy test does not cover it", e.Name())
				continue
			}
			n := e.Name()
			seen[n] = true
			if n == "go.mod" || n == "go.sum" || n == "celeris" { // celeris = the built binary, .gitignored
				continue
			}
			a, err1 := os.ReadFile(filepath.Join("celeris", n))
			b, err2 := os.ReadFile(filepath.Join(mod, n))
			if err1 != nil || err2 != nil {
				t.Errorf("%s/%s: %v / %v", mod, n, err1, err2)
				continue
			}
			if !bytes.Equal(a, b) {
				t.Errorf("servers/%s/%s differs from servers/celeris/%s", mod, n, n)
			}
		}
		ents2, _ := os.ReadDir(mod)
		for _, e := range ents2 {
			if n := e.Name(); !seen[n] && n != mod { // the built binary is named after the directory
				t.Errorf("servers/%s/%s has no counterpart in servers/celeris", mod, n)
			}
		}
		ma, _ := os.ReadFile(filepath.Join("celeris", "go.mod"))
		mb, _ := os.ReadFile(filepath.Join(mod, "go.mod"))
		norm := func(b []byte, m, pin string) string {
			return strings.ReplaceAll(strings.ReplaceAll(string(b), "servers/"+m, "servers/MOD"), pin, "PIN")
		}
		if norm(ma, "celeris", l756hPin(t, "celeris")) != norm(mb, mod, l756hPin(t, mod)) {
			t.Errorf("go.mod of servers/%s differs from servers/celeris by more than the module path and the celeris pin", mod)
		}
	}
}
